INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_111'), 1, 'Count every client of the database, not only the api: who else keeps a connection open, and which slots can an ordinary role never take?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_111'), 2, 'In transaction pooling, a client keeps a server connection only for the length of one transaction. Where does a plain `SET` live, and where does the next transaction run?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_111'), 3, 'Read SHOW POOLS column by column: `cl_` columns are clients of PgBouncer, `sv_` columns are its connections to PostgreSQL. Which side is short?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_111'), 'After the outage the team wants the smallest change:

```text
FATAL:  sorry, too many clients already

max_connections                = 100
superuser_reserved_connections = 3
connections from other clients  = 7    (migrate job, metrics exporter, two psql sessions)
HPA maxReplicas                = 12
node-postgres Pool({ max })    = 20
```

Statement: "Lowering the pool to `max: 8` fixes it: 12 pods x 8 = 96 connections, under max_connections 100."', 'single_choice'::question_type, 'False. 100 is not what the api gets: 3 slots are reserved for superusers and 7 are taken by other clients, so ordinary roles have 90. 96 still fails at full scale, and the next raise of maxReplicas breaks it again. Budget = max_connections - reserved - other clients, divided by the HPA''s maximum (90 / 12 = 7 per pod), or put PgBouncer in front so the pods'' pools stop mapping one to one onto server connections.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_111'), 'With PgBouncer in `pool_mode = transaction`, the multi-tenant report sometimes reads the wrong schema:

```sql
-- request 1, outside any transaction
SET search_path TO tenant_42;
SELECT count(*) FROM orders;      -- tenant_42.orders
-- request 2 from the same pod, a moment later
SELECT count(*) FROM orders;      -- ERROR: relation "orders" does not exist
```

Statement: "Each transaction may run on a different server connection, so the session-level SET stayed on another connection; `SET LOCAL search_path` inside the report''s transaction (or a schema-qualified name) works in transaction mode."', 'single_choice'::question_type, 'True. In transaction mode PgBouncer hands a server connection to a client for one transaction and takes it back. A plain `SET` changes that server session, which the next transaction (maybe another client''s) inherits, while this client''s next query lands on a different connection. `SET LOCAL` lasts until the end of the current transaction, so it travels with the work. The same goes for session advisory locks (`pg_advisory_lock`) vs `pg_advisory_xact_lock`. The misconception is that a pod''s connection stays the same server connection.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
