INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_112', (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-1-1' AND is_deleted = false LIMIT 1), 'connection-planner', 'Plan connections before you scale', 'Rice Rocket wants a check that runs before anyone raises the HPA''s maxReplicas or a pool size. The editor holds `pool_planner.py` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that `plan(case)` reports, for one scenario: the server connections the api may use (`max_connections` minus `superuser_reserved_connections` minus other clients); the connections the api opens with every pod of the HPA''s maximum holding a full pool; the server connections PostgreSQL sees at peak with no PgBouncer, or with PgBouncer in session, transaction or statement mode (capped by `default_pool_size`, the rest waiting); whether PostgreSQL or PgBouncer refuses clients; and which of the api''s features the pool mode breaks. The docstring at the top of the file is the exact contract.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
