INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 1, 'Work one scenario by hand first: 12 pods, pool 20, 6 transactions per pod at peak, PgBouncer pool 40. How many client connections, how many transactions at once, how many server connections, how many waiting?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 2, 'There are three numbers to get right (available, clients, needed) and one table (which features keep state in the server session). `min()` caps the server side; the difference is the queue.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 3, 'A worker fleet of 4-10 pods with `pool_max` 5 behind PgBouncer in session mode with `default_pool_size` 30: clients = 10 x 5 = 50; session mode needs one server connection per client, so needed = 50, server = min(50, 30) = 30 and 20 wait. In transaction mode with 2 transactions per pod at peak, needed = 10 x 2 = 20 and nobody waits.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"mode-rules","label":"What each PgBouncer pool mode breaks","code":"# State that lives in a server session: a later transaction may run on another connection.\nSESSION_STATE = {\"session_set\", \"listen_notify\", \"session_advisory_lock\", \"temp_table\", \"with_hold_cursor\"}\nBROKEN = {\n    \"session\": set(),\n    \"transaction\": SESSION_STATE,\n    \"statement\": SESSION_STATE | {\"multi_statement_transaction\"},\n}"},{"id":"available-connections","label":"Server connections the api may use","code":"available = server[\"max_connections\"] - server[\"superuser_reserved_connections\"] - server[\"other_clients\"]"},{"id":"client-connections","label":"Connections the api opens at the worst moment","code":"clients = app[\"max_pods\"] * app[\"pool_max\"]"},{"id":"server-demand","label":"Server connections the pool mode needs at peak","code":"needed = clients if mode == \"session\" else peak_active"},{"id":"pool-cap","label":"What default_pool_size lets through, and who waits","code":"server_connections = min(needed, bouncer[\"default_pool_size\"])\nwaiting = needed - server_connections"},{"id":"available-no-reserved","label":"Server connections the api may use","code":"available = server[\"max_connections\"] - server[\"other_clients\"]","distractor":true},{"id":"clients-min-pods","label":"Connections the api opens at the worst moment","code":"clients = app[\"min_pods\"] * app[\"pool_max\"]","distractor":true},{"id":"mode-rules-set-local","label":"What each PgBouncer pool mode breaks","code":"# State that lives in a server session: a later transaction may run on another connection.\nSESSION_STATE = {\"set_local\", \"listen_notify\", \"session_advisory_lock\", \"xact_advisory_lock\", \"temp_table\"}\nBROKEN = {\n    \"session\": set(),\n    \"transaction\": SESSION_STATE,\n    \"statement\": SESSION_STATE | {\"multi_statement_transaction\"},\n}","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 'The incident: 12 pods x pool 20 straight to PostgreSQL is too many clients', '{"server":{"max_connections":100,"superuser_reserved_connections":3,"other_clients":7},"app":{"min_pods":3,"max_pods":12,"pool_max":20,"peak_active_per_pod":6},"pgbouncer":null,"features":["session_set","set_local","xact_advisory_lock","session_advisory_lock","prepared_statements"]}', '{"available":90,"client_connections":240,"server_connections":240,"too_many_clients":true,"pgbouncer_refused":false,"waiting_at_peak":0,"broken_features":[]}', 6, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 'Transaction mode: 72 transactions at peak, pool of 40, 32 wait; session SET and session locks break', '{"server":{"max_connections":100,"superuser_reserved_connections":3,"other_clients":7},"app":{"min_pods":3,"max_pods":12,"pool_max":20,"peak_active_per_pod":6},"pgbouncer":{"pool_mode":"transaction","default_pool_size":40,"max_client_conn":400,"max_prepared_statements":200},"features":["session_set","set_local","xact_advisory_lock","session_advisory_lock","prepared_statements"]}', '{"available":90,"client_connections":240,"server_connections":40,"too_many_clients":false,"pgbouncer_refused":false,"waiting_at_peak":32,"broken_features":["session_set","session_advisory_lock"]}', 6, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 'Session mode holds a server connection per client: a pool of 100 is over the 90 available', '{"server":{"max_connections":100,"superuser_reserved_connections":3,"other_clients":7},"app":{"min_pods":3,"max_pods":12,"pool_max":20,"peak_active_per_pod":6},"pgbouncer":{"pool_mode":"session","default_pool_size":100,"max_client_conn":400},"features":["session_set","set_local","xact_advisory_lock","session_advisory_lock","prepared_statements"]}', '{"available":90,"client_connections":240,"server_connections":100,"too_many_clients":true,"pgbouncer_refused":false,"waiting_at_peak":140,"broken_features":[]}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 'Statement mode breaks transactions; prepared statements break without max_prepared_statements', '{"server":{"max_connections":100,"superuser_reserved_connections":3,"other_clients":7},"app":{"min_pods":3,"max_pods":12,"pool_max":20,"peak_active_per_pod":2},"pgbouncer":{"pool_mode":"statement","default_pool_size":40,"max_client_conn":400},"features":["multi_statement_transaction","set_local","prepared_statements","listen_notify","with_hold_cursor","temp_table"]}', '{"available":90,"client_connections":240,"server_connections":24,"too_many_clients":false,"pgbouncer_refused":false,"waiting_at_peak":0,"broken_features":["multi_statement_transaction","prepared_statements","listen_notify","with_hold_cursor","temp_table"]}', 6, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_112'), 'PgBouncer refuses clients over max_client_conn; a smaller server keeps 3 slots for superusers', '{"server":{"max_connections":50,"superuser_reserved_connections":3,"other_clients":5},"app":{"min_pods":2,"max_pods":10,"pool_max":25,"peak_active_per_pod":4},"pgbouncer":{"pool_mode":"transaction","default_pool_size":45,"max_client_conn":200,"max_prepared_statements":0},"features":["xact_advisory_lock","prepared_statements"]}', '{"available":42,"client_connections":250,"server_connections":40,"too_many_clients":false,"pgbouncer_refused":true,"waiting_at_peak":0,"broken_features":["prepared_statements"]}', 6, false, true, 5);
