INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_122', (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-1-2' AND is_deleted = false LIMIT 1), 'session-watchdog', 'Fix the session watchdog', 'After the stuck checkout, a teammate wrote a watchdog that reads `pg_stat_activity` every 30 seconds. In its first week it killed the replication connection, cut off pooled sessions that were only waiting for work, and left the next stuck checkout alone. The editor holds `watchdog.py` with its decision blocks missing, each marked by a `# [ ]` line; some pieces are last week''s buggy versions. Fill every line so that the watchdog: never touches its own session, non-client backends or plain `idle` sessions; terminates sessions idle in a transaction longer than the limit, counted from when they went idle (`state_change`); cancels active queries running longer than the limit, counted from `query_start`; and recommends the `ALTER ROLE` settings that make PostgreSQL do this itself. The docstring is the exact contract.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
