VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_122'), 'The incident: terminate the stuck checkout, cancel the blocked one, leave pooled idle sessions', '{"now":1000000,"my_pid":4242,"limits":{"idle_in_transaction_s":30,"statement_s":60},"rows":[{"pid":31337,"usename":"api","backend_type":"client backend","state":"idle in transaction","xact_start":999815,"query_start":999818,"state_change":999820,"wait_event_type":null,"query":"SELECT * FROM orders WHERE id = $1 FOR UPDATE"},{"pid":31400,"usename":"api","backend_type":"client backend","state":"active","xact_start":999998,"query_start":999998,"state_change":999998,"wait_event_type":null,"query":"SELECT * FROM restaurants WHERE id = $1"},{"pid":31401,"usename":"api","backend_type":"client backend","state":"active","xact_start":999829,"query_start":999830,"state_change":999830,"wait_event_type":"Lock","query":"SELECT * FROM orders WHERE id = $1 FOR UPDATE"},{"pid":31600,"usename":"api","backend_type":"client backend","state":"idle","xact_start":null,"query_start":999100,"state_change":999101,"wait_event_type":null,"query":"COMMIT"}]}', '{"terminate":[[31337,"idle in transaction for 180s"]],"cancel":[[31401,"query running for 170s"]],"alter_role":["ALTER ROLE api SET idle_in_transaction_session_timeout = ''30s''","ALTER ROLE api SET statement_timeout = ''60s''"]}', 8, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_122'), 'The 40-minute analytics query is cancelled; replication, autovacuum and the watchdog are not', '{"now":1000000,"my_pid":4242,"limits":{"idle_in_transaction_s":30,"statement_s":60},"rows":[{"pid":4242,"usename":"watchdog","backend_type":"client backend","state":"active","xact_start":1000000,"query_start":1000000,"state_change":1000000,"wait_event_type":null,"query":"SELECT * FROM pg_stat_activity"},{"pid":9001,"usename":"replicator","backend_type":"walsender","state":"active","xact_start":null,"query_start":913600,"state_change":913600,"wait_event_type":null,"query":"START_REPLICATION SLOT standby_1"},{"pid":9002,"usename":null,"backend_type":"autovacuum worker","state":"active","xact_start":999100,"query_start":999100,"state_change":999100,"wait_event_type":null,"query":"autovacuum: VACUUM public.order_events"},{"pid":31500,"usename":"analytics","backend_type":"client backend","state":"active","xact_start":997600,"query_start":997600,"state_change":997600,"wait_event_type":null,"query":"SELECT date_trunc(''hour'', created_at), count(*) FROM orders GROUP BY 1"}]}', '{"terminate":[],"cancel":[[31500,"query running for 2400s"]],"alter_role":["ALTER ROLE analytics SET idle_in_transaction_session_timeout = ''30s''","ALTER ROLE analytics SET statement_timeout = ''60s''"]}', 8, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_122'), 'A long transaction idle for only 10s is left alone; an aborted one idle for 45s is terminated', '{"now":1000000,"my_pid":4242,"limits":{"idle_in_transaction_s":30,"statement_s":60},"rows":[{"pid":31700,"usename":"api","backend_type":"client backend","state":"idle in transaction","xact_start":999600,"query_start":999940,"state_change":999990,"wait_event_type":null,"query":"UPDATE orders SET status = ''archived'' WHERE created_at < $1"},{"pid":31701,"usename":"courier","backend_type":"client backend","state":"idle in transaction (aborted)","xact_start":999950,"query_start":999954,"state_change":999955,"wait_event_type":null,"query":"INSERT INTO courier_pings VALUES ($1, $2, $3)"}]}', '{"terminate":[[31701,"idle in transaction for 45s"]],"cancel":[],"alter_role":["ALTER ROLE courier SET idle_in_transaction_session_timeout = ''30s''","ALTER ROLE courier SET statement_timeout = ''60s''"]}', 7, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_122'), 'A quiet database: old idle pooled sessions and short queries give an empty decision', '{"now":1000000,"my_pid":4242,"limits":{"idle_in_transaction_s":30,"statement_s":60},"rows":[{"pid":31800,"usename":"api","backend_type":"client backend","state":"idle","xact_start":null,"query_start":996400,"state_change":996400,"wait_event_type":null,"query":"SELECT 1"},{"pid":31801,"usename":"api","backend_type":"client backend","state":"idle","xact_start":null,"query_start":999880,"state_change":999881,"wait_event_type":null,"query":"COMMIT"},{"pid":31802,"usename":"api","backend_type":"client backend","state":"active","xact_start":999999,"query_start":999999,"state_change":999999,"wait_event_type":null,"query":"SELECT * FROM couriers WHERE zone = $1"},{"pid":31803,"usename":"api","backend_type":"client backend","state":"idle in transaction","xact_start":999997,"query_start":999998,"state_change":999998,"wait_event_type":null,"query":"SELECT * FROM carts WHERE id = $1"}]}', '{"terminate":[],"cancel":[],"alter_role":[]}', 7, false, true, 4);
