VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_142'), 'The incident''s ADD COLUMN with a constant or now() default: catalog only, needs lock_timeout', '{"pg_version":17,"statements":["ALTER TABLE orders ADD COLUMN tip_vnd integer DEFAULT 0;","ALTER TABLE orders ADD COLUMN accepted_at timestamptz DEFAULT now()"]}', '[{"sql":"ALTER TABLE orders ADD COLUMN tip_vnd integer DEFAULT 0","lock":"ACCESS EXCLUSIVE","work":"catalog only","verdict":"needs lock_timeout","fix":["SET lock_timeout = ''3s''","ALTER TABLE orders ADD COLUMN tip_vnd integer DEFAULT 0"]},{"sql":"ALTER TABLE orders ADD COLUMN accepted_at timestamptz DEFAULT now()","lock":"ACCESS EXCLUSIVE","work":"catalog only","verdict":"needs lock_timeout","fix":["SET lock_timeout = ''3s''","ALTER TABLE orders ADD COLUMN accepted_at timestamptz DEFAULT now()"]}]', 7, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_142'), 'A volatile default rewrites the table and is split into add, set default and backfill', '{"pg_version":17,"statements":["ALTER TABLE orders ADD COLUMN public_id uuid DEFAULT gen_random_uuid()"]}', '[{"sql":"ALTER TABLE orders ADD COLUMN public_id uuid DEFAULT gen_random_uuid()","lock":"ACCESS EXCLUSIVE","work":"rewrites the table","verdict":"unsafe","fix":["SET lock_timeout = ''3s''","ALTER TABLE orders ADD COLUMN public_id uuid","ALTER TABLE orders ALTER COLUMN public_id SET DEFAULT gen_random_uuid()","-- backfill existing rows in batches"]}]', 7, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_142'), 'CREATE INDEX blocks writes; the fix builds it concurrently, outside any transaction', '{"pg_version":17,"statements":["CREATE INDEX orders_courier_id_idx ON orders (courier_id)","CREATE UNIQUE INDEX CONCURRENTLY orders_public_id_key ON orders (public_id)"]}', '[{"sql":"CREATE INDEX orders_courier_id_idx ON orders (courier_id)","lock":"SHARE","work":"builds an index","verdict":"unsafe","fix":["CREATE INDEX CONCURRENTLY orders_courier_id_idx ON orders (courier_id)"]},{"sql":"CREATE UNIQUE INDEX CONCURRENTLY orders_public_id_key ON orders (public_id)","lock":"SHARE UPDATE EXCLUSIVE","work":"builds an index","verdict":"safe","fix":["CREATE UNIQUE INDEX CONCURRENTLY orders_public_id_key ON orders (public_id)"]}]', 7, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_142'), 'A foreign key is added NOT VALID, then validated under a lock that lets writes through', '{"pg_version":17,"statements":["ALTER TABLE orders ADD CONSTRAINT orders_courier_fk FOREIGN KEY (courier_id) REFERENCES couriers (id)","ALTER TABLE orders VALIDATE CONSTRAINT orders_courier_fk"]}', '[{"sql":"ALTER TABLE orders ADD CONSTRAINT orders_courier_fk FOREIGN KEY (courier_id) REFERENCES couriers (id)","lock":"SHARE ROW EXCLUSIVE","work":"scans the table","verdict":"unsafe","fix":["SET lock_timeout = ''3s''","ALTER TABLE orders ADD CONSTRAINT orders_courier_fk FOREIGN KEY (courier_id) REFERENCES couriers (id) NOT VALID","ALTER TABLE orders VALIDATE CONSTRAINT orders_courier_fk"]},{"sql":"ALTER TABLE orders VALIDATE CONSTRAINT orders_courier_fk","lock":"SHARE UPDATE EXCLUSIVE","work":"scans the table","verdict":"safe","fix":["ALTER TABLE orders VALIDATE CONSTRAINT orders_courier_fk"]}]', 6, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_142'), 'SET NOT NULL through a CHECK constraint, a type change, a rename and a drop', '{"pg_version":17,"statements":["ALTER TABLE orders ALTER COLUMN restaurant_id SET NOT NULL","ALTER TABLE orders ALTER COLUMN total_vnd TYPE bigint","ALTER TABLE orders RENAME COLUMN note TO customer_note","ALTER TABLE orders DROP COLUMN legacy_status"]}', '[{"sql":"ALTER TABLE orders ALTER COLUMN restaurant_id SET NOT NULL","lock":"ACCESS EXCLUSIVE","work":"scans the table","verdict":"unsafe","fix":["SET lock_timeout = ''3s''","ALTER TABLE orders ADD CONSTRAINT orders_restaurant_id_not_null CHECK (restaurant_id IS NOT NULL) NOT VALID","ALTER TABLE orders VALIDATE CONSTRAINT orders_restaurant_id_not_null","ALTER TABLE orders ALTER COLUMN restaurant_id SET NOT NULL","ALTER TABLE orders DROP CONSTRAINT orders_restaurant_id_not_null"]},{"sql":"ALTER TABLE orders ALTER COLUMN total_vnd TYPE bigint","lock":"ACCESS EXCLUSIVE","work":"rewrites the table","verdict":"unsafe","fix":["-- expand and contract: add a new column, backfill in batches, switch reads, drop the old one later"]},{"sql":"ALTER TABLE orders RENAME COLUMN note TO customer_note","lock":"ACCESS EXCLUSIVE","work":"catalog only","verdict":"unsafe","fix":["-- expand and contract: add a new column, backfill in batches, switch reads, drop the old one later"]},{"sql":"ALTER TABLE orders DROP COLUMN legacy_status","lock":"ACCESS EXCLUSIVE","work":"catalog only","verdict":"needs lock_timeout","fix":["SET lock_timeout = ''3s''","ALTER TABLE orders DROP COLUMN legacy_status"]}]', 6, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_142'), 'On PostgreSQL 10 any default rewrites and SET NOT NULL has no shortcut', '{"pg_version":10,"statements":["ALTER TABLE orders ADD COLUMN tip_vnd integer DEFAULT 0","ALTER TABLE orders ALTER COLUMN restaurant_id SET NOT NULL","VACUUM orders"]}', '[{"sql":"ALTER TABLE orders ADD COLUMN tip_vnd integer DEFAULT 0","lock":"ACCESS EXCLUSIVE","work":"rewrites the table","verdict":"unsafe","fix":["SET lock_timeout = ''3s''","ALTER TABLE orders ADD COLUMN tip_vnd integer","ALTER TABLE orders ALTER COLUMN tip_vnd SET DEFAULT 0","-- backfill existing rows in batches"]},{"sql":"ALTER TABLE orders ALTER COLUMN restaurant_id SET NOT NULL","lock":"ACCESS EXCLUSIVE","work":"scans the table","verdict":"unsafe","fix":["SET lock_timeout = ''3s''","ALTER TABLE orders ALTER COLUMN restaurant_id SET NOT NULL"]},{"sql":"VACUUM orders","lock":"unknown","work":"unknown","verdict":"review","fix":["VACUUM orders"]}]', 7, false, true, 6);
