INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_151'), 1, '`total_exec_time` is `calls` times `mean_exec_time`: which number says where the database spends its time, and which one says how one request feels?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_151'), 2, 'In the plan, look at the index name, the `Index Cond` (what the index narrows down) and the `Filter` with `Rows Removed by Filter` (what was read and thrown away).'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_151'), 3, 'Every index on a table is a second structure that INSERT has to update. Which view counts how often each index was used since the statistics were reset?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_151');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_151'), 'The top of `pg_stat_statements`, sorted by total time:

```text
 query                                              | calls   | mean_exec_time | total_exec_time
----------------------------------------------------+---------+----------------+-----------------
 SELECT ... FROM orders WHERE restaurant_id = $1 .. | 2104311 |       0.41 ms  |       862 768 ms
 SELECT ... FROM orders WHERE customer_id = $1 ...  |  611204 |       0.96 ms  |       586 756 ms
 SELECT ... FROM daily_report WHERE day = $1        |     312 |    1180.00 ms  |       368 160 ms
```

Statement: "The daily report is where the database spends most of its time, because its mean is over a thousand times higher than the others; it should be fixed first."', 'single_choice'::question_type, 'False. `total_exec_time` (calls x mean) is the time the server spent, and the restaurant query alone took 863 seconds, more than twice the report''s 368 seconds, because it runs two million times. The report is the slowest single query and may be worth fixing for the people who wait for it, but halving the restaurant query frees far more of the database. The misconception is ranking by mean time, which hides cheap queries that run constantly.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_151') AND order_index = 1)
    RETURNING id
)
