WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_151'), 'Inserts into `orders` slowed down after someone added an index on every column:

```sql
SELECT indexrelname, idx_scan, pg_size_pretty(pg_relation_size(indexrelid)) AS size
FROM pg_stat_user_indexes WHERE relname = ''orders'' ORDER BY idx_scan;
```

```text
 indexrelname             | idx_scan | size
--------------------------+----------+--------
 orders_total_vnd_idx     |        0 | 214 MB
 orders_status_idx        |        0 | 188 MB
 orders_created_at_idx    |       12 | 214 MB
 orders_courier_id_idx    |   981233 | 201 MB
```

Statement: "Every INSERT into `orders` also writes an entry into each of its indexes, so dropping the indexes that no query uses (`idx_scan` = 0 over a representative period) makes inserts cheaper without slowing any query."', 'single_choice'::question_type, 'True. A new row has to be added to every index of the table, and each index also costs WAL, vacuum work and cache memory. `pg_stat_user_indexes.idx_scan` counts how often each index was used since the statistics were last reset, so check that the period covers month-end jobs and rare reports before dropping. Drop with `DROP INDEX CONCURRENTLY` so the table stays writable. The misconception is that an unused index is free.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_151') AND order_index = 3)
    RETURNING id
)
