INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_152', (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-3-1' AND is_deleted = false LIMIT 1), 'indexes-from-slow-queries', 'Replace one index per column with the indexes the queries need', 'The `orders` table has one index on each of seven columns: inserts are slower and the three slow queries are still slow. The editor holds `migrations/0042_orders_indexes.py` with its SQL pieces missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: the one-column indexes no query needs are dropped (keep `orders_courier_id_idx`); the restaurant tablet query (active orders of one restaurant, newest first) searches an index that holds only the `pending` and `cooking` orders and needs no sort; the customer history query searches on the customer and the date range; support''s lookup uses a UNIQUE index on `public_code`; every query returns exactly what it returned before, and the table ends with 4 indexes. Run builds the table on SQLite, applies your pieces and prints each query''s plan from `EXPLAIN QUERY PLAN`.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
