INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_152'), 'The restaurant query searches an active-orders index by restaurant and needs no sort', '{"checks":["plans"],"queries":["active"],"params":{"active":{"restaurant_id":3},"history":{"customer_id":11,"from":"2026-10-05","to":"2026-10-20"},"lookup":{"code":"RR-00042"},"courier":{"courier_id":4}}}', '{"plans":{"active":{"index":"orders_active_by_restaurant","constraint":"restaurant_id=?","temp_sort":false}}}', 8, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_152'), 'The customer history query searches on the customer and the date range', '{"checks":["plans"],"queries":["history"],"params":{"active":{"restaurant_id":3},"history":{"customer_id":11,"from":"2026-10-05","to":"2026-10-20"},"lookup":{"code":"RR-00042"},"courier":{"courier_id":4}}}', '{"plans":{"history":{"index":"orders_by_customer_created","constraint":"customer_id=? AND created_at>? AND created_at<?","temp_sort":false}}}', 8, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_152'), 'Four indexes remain and every query returns the same rows as before', '{"checks":["indexes","same_results"],"params":{"active":{"restaurant_id":3},"history":{"customer_id":11,"from":"2026-10-05","to":"2026-10-20"},"lookup":{"code":"RR-00042"},"courier":{"courier_id":4}}}', '{"indexes":["orders_active_by_restaurant","orders_by_customer_created","orders_courier_id_idx","orders_public_code_key"],"same_results":true}', 8, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_152'), 'public_code is unique and support''s lookup searches that index', '{"checks":["plans","duplicate_code"],"queries":["lookup"],"params":{"active":{"restaurant_id":3},"history":{"customer_id":11,"from":"2026-10-05","to":"2026-10-20"},"lookup":{"code":"RR-00042"},"courier":{"courier_id":4}}}', '{"plans":{"lookup":{"index":"orders_public_code_key","constraint":"public_code=?","temp_sort":false}},"duplicate_code":"IntegrityError: UNIQUE constraint failed: orders.public_code"}', 8, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_152'), 'Other data and parameters: all four plans and results hold', '{"checks":["plans","same_results"],"params":{"active":{"restaurant_id":9},"history":{"customer_id":27,"from":"2026-10-01","to":"2026-10-31"},"lookup":{"code":"RR-00777"},"courier":{"courier_id":18}},"rows":900,"seed":21}', '{"plans":{"active":{"index":"orders_active_by_restaurant","constraint":"restaurant_id=?","temp_sort":false},"history":{"index":"orders_by_customer_created","constraint":"customer_id=? AND created_at>? AND created_at<?","temp_sort":false},"lookup":{"index":"orders_public_code_key","constraint":"public_code=?","temp_sort":false},"courier":{"index":"orders_courier_id_idx","constraint":"courier_id=?","temp_sort":false}},"same_results":true}', 8, false, true, 5);
