INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_162', (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-3-2' AND is_deleted = false LIMIT 1), 'keyset-pagination', 'Page the admin order list with a keyset cursor', 'The admin order list pages through one restaurant''s orders, newest first, with OFFSET: deep pages are slow, and while new orders arrive staff see some orders twice and miss others. The editor holds `admin/order_pages.py` with its key pieces missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that `fetch_page` orders by `created_at DESC, id DESC`, starts each next page strictly after the last row of the previous one with a row-value comparison, hands the browser an opaque cursor (URL-safe base64 of JSON `{"created_at", "id"}`), rejects any other cursor with `InvalidCursor("invalid cursor")`, and has an index that serves both queries without a sort. Many orders share one second. Run pages through a restaurant on SQLite while new orders arrive between pages, and reports ids seen twice, ids never shown and the query plans.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
