INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_162'), 1, 'Ask what identifies "where the last page ended" when three orders share the same second, and which rows the next query must return relative to that point, whatever was inserted in between.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_162'), 2, 'Look at a unique ORDER BY (add the primary key as the last column), a row-value comparison `(a, b) < (:a, :b)`, an index whose columns are the filter column then the ORDER BY columns, and `base64.urlsafe_b64encode` / `binascii.Error`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_162'), 3, 'Paging a courier''s delivery log by `(delivered_at, id)` oldest first: `WHERE courier_id = :c AND (delivered_at, id) > (:delivered_at, :id) ORDER BY delivered_at, id LIMIT :n`, with `CREATE INDEX deliveries_courier_time_id ON deliveries (courier_id, delivered_at, id)`, and a cursor built from the last row''s `delivered_at` and `id`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_162'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"page-index","label":"Index that serves the list''s filter and order","code":"PAGE_INDEX = \"CREATE INDEX orders_restaurant_created_id ON orders (restaurant_id, created_at, id)\""},{"id":"first-page","label":"Query for the first page","code":"Q_FIRST = \"\"\"\nSELECT id, created_at FROM orders\nWHERE restaurant_id = :restaurant_id\nORDER BY created_at DESC, id DESC\nLIMIT :page_size\n\"\"\""},{"id":"next-page","label":"Query for the page after a cursor","code":"Q_NEXT = \"\"\"\nSELECT id, created_at FROM orders\nWHERE restaurant_id = :restaurant_id\n  AND (created_at, id) < (:created_at, :id)\nORDER BY created_at DESC, id DESC\nLIMIT :page_size\n\"\"\""},{"id":"encode-cursor","label":"Turn the last row of a page into a cursor","code":"def encode_cursor(row):\n    data = json.dumps({\"created_at\": row[1], \"id\": row[0]}, separators=(\",\", \":\"))\n    return base64.urlsafe_b64encode(data.encode()).decode()"},{"id":"decode-cursor","label":"Read a cursor back, rejecting anything else","code":"def decode_cursor(cursor):\n    try:\n        data = json.loads(base64.urlsafe_b64decode(cursor.encode()))\n    except (binascii.Error, UnicodeDecodeError, ValueError):\n        raise InvalidCursor(\"invalid cursor\")\n    if not isinstance(data, dict) or set(data) != {\"created_at\", \"id\"} \\\n            or not isinstance(data[\"created_at\"], str) or type(data[\"id\"]) is not int:\n        raise InvalidCursor(\"invalid cursor\")\n    return data"},{"id":"decode-cursor-unchecked","label":"Read a cursor back, rejecting anything else","code":"def decode_cursor(cursor):\n    return json.loads(base64.urlsafe_b64decode(cursor.encode()))","distractor":true},{"id":"encode-cursor-created-only","label":"Turn the last row of a page into a cursor","code":"def encode_cursor(row):\n    data = json.dumps({\"created_at\": row[1]}, separators=(\",\", \":\"))\n    return base64.urlsafe_b64encode(data.encode()).decode()","distractor":true},{"id":"next-page-no-tiebreak","label":"Query for the page after a cursor","code":"Q_NEXT = \"\"\"\nSELECT id, created_at FROM orders\nWHERE restaurant_id = :restaurant_id\n  AND created_at < :created_at\nORDER BY created_at DESC, id DESC\nLIMIT :page_size\n\"\"\"","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
