INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171'), 1, 'A logical dump is one consistent snapshot. Ask at which moment that snapshot was taken, and what happened to the database between that moment and 14:05.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171'), 2, 'Point-in-time recovery starts from a base backup and replays WAL forward from the moment that backup started. Which files must exist, without a hole, for a target time three days back?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171'), 3, 'Think about what else the production database received after 14:05, and where the restored copy should run while you compare and copy rows.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171'), 'The nightly backup job and the incident, both on 3 November:

```text
$ grep rice_rocket /var/log/backup.log | tail -2
2026-11-03 02:00:01 pg_dump --format=custom --file=rice_rocket-2026-11-03.dump rice_rocket
2026-11-03 02:18:44 done, 40 GB

# application log
2026-11-03 14:05:12 migration 0142_cleanup_orders: DELETE 9000
```

Statement: "Restoring `rice_rocket-2026-11-03.dump` with `pg_restore` brings the database back to just before 14:05:12, so only the bad DELETE is undone."', 'single_choice'::question_type, 'False. pg_dump exports one consistent snapshot taken when it started (02:00). Restoring it brings back the database as it was at 02:00: every order, payment and courier update written between 02:00 and 14:05 is missing, about 12 hours of business. Getting to 14:05:11 needs point-in-time recovery: a physical base backup plus every WAL segment written since it started. The misconception is that a dump is a recovery point you can move forward.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171'), 'The backup settings of the self-managed staging server:

```text
base backups (pg_basebackup):  every Sunday 01:00, kept 7 days
WAL archive (archive_command): kept 3 days
today: Saturday

$ ls /backup/base
2026-11-01_0100/        # Sunday, 6 days ago
$ ls /backup/wal | head -1
00000001000000B200000041   # oldest segment, written Wednesday 15:20
```

Statement: "Because the base backups are kept 7 days, the server can be restored to any point in time of the last 7 days."', 'single_choice'::question_type, 'False. Recovery starts from a base backup and replays WAL from the moment that backup started. The only base backup started on Sunday, but WAL before Wednesday 15:20 has been deleted, so the replay cannot get from Sunday to any later point: the backup can only be restored to the moment it finished, and no time after it is reachable. The recovery window is limited by the shorter of the two retentions, and WAL must be kept at least from the start of the oldest base backup you rely on. The misconception is that each piece''s retention guarantees the window on its own.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171') AND order_index = 2)
    RETURNING id
)
