    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171'), 'The team prepares point-in-time recovery for the incident:

```text
# a NEW instance restored from base backup base-2026-11-03, with WAL from the archive
restore_command = ''cp /backup/wal/%f %p''
recovery_target_time = ''2026-11-03 14:05:11+07''
recovery_target_action = ''pause''

# application log
2026-11-03 14:05:12 migration 0142_cleanup_orders: DELETE 9000
```

Statement: "Recovering a new instance to one second before the DELETE and copying the 9,000 rows back is right; restoring the production instance itself to 14:05:11 would also throw away every order written since."', 'single_choice'::question_type, 'True. The restored instance holds the 9,000 orders as they were just before the DELETE committed; the team copies them back into production (for example `\copy` out and an `INSERT ... ON CONFLICT DO NOTHING` in), and production keeps everything written after 14:05. `recovery_target_time` stops after the transactions that committed at or before the target, so a target of exactly 14:05:12 could replay the DELETE itself. Rolling production back in time is the last resort: it loses every write since the target. The misconception is that a restore always goes onto the damaged server.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_171') AND order_index = 3)
    RETURNING id
)
