-- challenge chal_coding_pgp_172 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_172', (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-4-1' AND is_deleted = false LIMIT 1), 'restore-planner', 'Plan the point-in-time restore', 'Write the restore planner the on-call engineer runs after a bad write: given the backup catalog, the WAL archive, the commit time of the bad statement and the backup policy, it picks the base backup, the recovery target and the expected data loss and restore time, or falls back to a dump. The editor holds `restore_plan.py` with its helper functions missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. The rules are in the docstring: newest base backup that finished before the incident inside the retention window, a gap-free WAL chain from its start, a target one second before the incident, and a dump only when no base backup can be used.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_172');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_172'), 1, 'Walk the restore yourself: which base backups existed before 14:05:12, from which moment does each one need WAL, and where does the archive first stop being continuous?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_172'), 2, 'The helpers are small: a filter and sort over the catalog, a loop that extends the chain only while the next segment starts at or before its current end, a `min()` for the target, and the RTO formula from the docstring.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_172'), 3, 'A planner for restoring a deleted S3 object from versioned snapshots looks the same: keep the snapshots taken before the deletion and within retention, sort newest first, then walk the change log from that snapshot while it has no hole and stop just before the delete.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_172'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"choose-base","label":"Base backups that can be used, newest first","code":"def usable_base_backups(backups, incident, policy):\n    oldest = t(policy[\"now\"]) - timedelta(days=policy[\"retention_days\"])\n    usable = [b for b in backups if b[\"kind\"] == \"base\" and oldest <= t(b[\"finished_at\"]) < incident]\n    return sorted(usable, key=lambda b: t(b[\"finished_at\"]), reverse=True)"},{"id":"wal-chain","label":"End of the gap-free WAL chain from a start time","code":"def wal_chain_end(wal_archive, start):\n    end = start\n    for segment in sorted(wal_archive, key=lambda s: t(s[\"from\"])):\n        if t(segment[\"to\"]) <= end:\n            continue\n        if t(segment[\"from\"]) > end:\n            break\n        end = t(segment[\"to\"])\n    return end"},{"id":"set-target","label":"Where replay stops","code":"def recovery_target(incident, chain_end):\n    return min(incident - timedelta(seconds=1), chain_end)"},{"id":"estimate-rto","label":"Minutes to restore and replay","code":"def estimate_rto(base, target, policy):\n    replay_hours = (target - t(base[\"started_at\"])).total_seconds() / 3600\n    return math.ceil(base[\"size_gb\"] / policy[\"restore_gb_per_min\"] + replay_hours * policy[\"replay_min_per_wal_hour\"])"},{"id":"dump-fallback","label":"Without PITR, the newest dump before the incident","code":"dumps = [b for b in backups if b[\"kind\"] == \"dump\" and t(b[\"finished_at\"]) < incident]\nif not dumps:\n    return {\"status\": \"failed\", \"reason\": \"no backup finished before the incident\"}\ndump = max(dumps, key=lambda b: t(b[\"finished_at\"]))\nreturn {\n    \"status\": \"dump-only\",\n    \"dump\": dump[\"id\"],\n    \"data_loss_seconds\": int((incident - t(dump[\"started_at\"])).total_seconds()),\n    \"rto_minutes\": math.ceil(dump[\"size_gb\"] / policy[\"dump_restore_gb_per_min\"]),\n}"},{"id":"choose-base-newest","label":"Base backups that can be used, newest first","code":"def usable_base_backups(backups, incident, policy):\n    usable = [b for b in backups if b[\"kind\"] == \"base\"]\n    return sorted(usable, key=lambda b: t(b[\"finished_at\"]), reverse=True)","distractor":true},{"id":"set-target-at-incident","label":"Where replay stops","code":"def recovery_target(incident, chain_end):\n    return min(incident, chain_end)","distractor":true},{"id":"wal-chain-ignore-gaps","label":"End of the gap-free WAL chain from a start time","code":"def wal_chain_end(wal_archive, start):\n    return max(t(segment[\"to\"]) for segment in wal_archive)","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_172');
