-- challenge chal_quiz_pgp_181 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pgp_181', (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-4-2' AND is_deleted = false LIMIT 1), 'vacuum-bloat-quiz', 'Read the bloated courier_locations table', 'Three statements about why courier_locations grew from 200 MB to 9 GB while the dashboards showed a healthy database. Decide whether each one is true.', 'open', 'hard'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181'), 1, 'An UPDATE in PostgreSQL writes a new row version and leaves the old one behind. Ask what plain VACUUM does with the space of a removed version, and what it takes to hand pages back to the operating system.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181'), 2, 'A dead row can only be removed when no transaction could still need it. Look for the oldest snapshot in the system: sessions, replication slots, prepared transactions.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181'), 3, 'Compute the autovacuum trigger yourself: threshold + scale_factor x reltuples, with the table''s own storage parameters where it has them.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181'), 'After the session that blocked cleanup was gone, the team ran a manual vacuum:

```sql
SELECT pg_size_pretty(pg_total_relation_size(''courier_locations''));
--  9012 MB
VACUUM (VERBOSE) courier_locations;
-- INFO:  finished vacuuming "rice_rocket.public.courier_locations": index scans: 1
-- tuples: 4796210 removed, 120034 remain, 0 are dead but not yet removable
SELECT pg_size_pretty(pg_total_relation_size(''courier_locations''));
--  8987 MB
```

Statement: "The VACUUM did not work: a successful VACUUM gives the space of the 4.8 million removed rows back to the operating system, so the table should now be about 200 MB."', 'single_choice'::question_type, 'False. The VACUUM worked: 4,796,210 dead versions were removed and their space is now free for new rows inside the table''s files. Plain VACUUM only returns space to the operating system when whole pages at the end of the file become empty, which is rare for a table updated everywhere. Shrinking the file needs a rewrite: `VACUUM FULL` (takes an ACCESS EXCLUSIVE lock for the whole rewrite) or `pg_repack` (rebuilds online, with brief locks). The misconception is that free space inside the table and file size are the same thing.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181'), 'Before that, autovacuum ran every few minutes on the table and nothing changed:

```text
LOG:  automatic vacuum of table "rice_rocket.public.courier_locations": index scans: 0
      tuples: 1203 removed, 118797 remain, 4796210 are dead but not yet removable
      removable cutoff: 81234567, which was 9012345 XIDs old when operation ended

=# SELECT pid, state, now() - xact_start AS open_for, age(backend_xmin)
   FROM pg_stat_activity WHERE backend_xmin IS NOT NULL ORDER BY 4 DESC LIMIT 1;
  pid  |        state        |    open_for     |   age
-------+---------------------+-----------------+---------
  4242 | idle in transaction | 3 days 02:11:07 | 9012345
```

Statement: "Session 4242, idle in a transaction for three days, holds the xmin horizon: every row version that died after its snapshot must be kept, so no vacuum can remove them until that transaction ends."', 'single_choice'::question_type, 'True. Vacuum may only remove a dead row version that no running transaction could still see. The removable cutoff is the oldest xmin in the system, here the snapshot of session 4242, 9 million transactions old; everything that died since is "dead but not yet removable". Ending the session (`pg_terminate_backend(4242)`) or its transaction lets the next vacuum clean up. The same horizon can be held by a replication slot with an old `xmin` or by a forgotten prepared transaction. The misconception is that an idle session costs nothing.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181'), 'The team gave the hot table its own autovacuum settings:

```sql
-- server defaults: autovacuum_vacuum_threshold = 50, autovacuum_vacuum_scale_factor = 0.2
SELECT reltuples FROM pg_class WHERE relname = ''courier_locations'';
--  120000
ALTER TABLE courier_locations SET (
  autovacuum_vacuum_scale_factor = 0.01,
  autovacuum_vacuum_threshold = 1000
);
```

Statement: "With these storage parameters, autovacuum starts on courier_locations after about 2,200 dead rows instead of about 24,050."', 'single_choice'::question_type, 'True. Autovacuum vacuums a table when its dead rows exceed `autovacuum_vacuum_threshold + autovacuum_vacuum_scale_factor * reltuples`. With the defaults that is 50 + 0.2 x 120,000 = 24,050; with the table''s own parameters 1,000 + 0.01 x 120,000 = 2,200. Per-table settings are the usual fix for a small table that is updated constantly. (PostgreSQL 18 also adds `autovacuum_vacuum_max_threshold`, a cap that matters for very large tables.) The misconception is that one server-wide scale factor suits every table.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pgp_181') AND order_index = 3)
    RETURNING id
)
