-- challenge chal_coding_pgp_182 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pgp_182', (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'postgres-in-production') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pgp-4-2' AND is_deleted = false LIMIT 1), 'vacuum-health-check', 'Fix the vacuum health check', 'The monitoring job''s vacuum check said "ok" for a month while courier_locations grew to 9 GB. Rebuild it from its pieces. For every table it must decide whether vacuum is due with the real autovacuum trigger (threshold + scale_factor x reltuples, the table''s storage parameters over the server settings), and report "blocked by pid <pid>" or "blocked by slot <name>" when a session or a replication slot holds the xmin horizon longer than `max_xmin_age` (the oldest one wins), "vacuum lagging" when vacuum is due and nothing blocks it, and "ok" otherwise. The editor holds `vacuum_check.py` with its functions missing, each marked by a `# [ ]` line; some pieces are last month''s bugs.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 1, 'Replay last month with the numbers in the tests: what threshold does autovacuum really use for courier_locations, and which object kept the dead rows alive?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 2, 'Check each piece against the docstring: settings merged with the table''s options, a sum (not a product) for the trigger, and both pg_stat_activity and pg_replication_slots for the horizon.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 3, 'A disk-usage alert follows the same shape: per volume, merge the default limits with the volume''s own, compare used space with base + percent x size, and when it is over, name the biggest process holding deleted-but-open files before calling it plain growth.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"effective-settings","label":"Autovacuum settings that apply to one table","code":"def table_settings(table, settings):\n    return {**settings, **table.get(\"options\", {})}"},{"id":"vacuum-threshold","label":"Dead rows that make autovacuum start","code":"def vacuum_threshold(table, params):\n    return params[\"autovacuum_vacuum_threshold\"] + params[\"autovacuum_vacuum_scale_factor\"] * table[\"reltuples\"]"},{"id":"find-blocker","label":"The session or slot that holds the xmin horizon back","code":"def find_blocker(sessions, slots, max_xmin_age):\n    holders = [(s[\"xmin_age\"], f\"pid {s[''pid'']}\") for s in sessions if s.get(\"xmin_age\") is not None]\n    holders += [(s[\"xmin_age\"], f\"slot {s[''slot_name'']}\") for s in slots if s.get(\"xmin_age\") is not None]\n    holders = [h for h in holders if h[0] > max_xmin_age]\n    return max(holders)[1] if holders else None"},{"id":"classify-due","label":"Status of a table that needs vacuum","code":"elif blocker:\n    result[table[\"relname\"]] = f\"blocked by {blocker}\"\nelse:\n    result[table[\"relname\"]] = \"vacuum lagging\""},{"id":"blocker-sessions-only","label":"The session or slot that holds the xmin horizon back","code":"def find_blocker(sessions, slots, max_xmin_age):\n    holders = [(s[\"xmin_age\"], f\"pid {s[''pid'']}\") for s in sessions if s.get(\"xmin_age\") is not None]\n    holders = [h for h in holders if h[0] > max_xmin_age]\n    return max(holders)[1] if holders else None","distractor":true},{"id":"settings-ignore-table-options","label":"Autovacuum settings that apply to one table","code":"def table_settings(table, settings):\n    return settings","distractor":true},{"id":"threshold-multiplied","label":"Dead rows that make autovacuum start","code":"def vacuum_threshold(table, params):\n    return params[\"autovacuum_vacuum_threshold\"] * params[\"autovacuum_vacuum_scale_factor\"] * table[\"reltuples\"]","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 'The incident: a session idle in transaction for 3 days blocks courier_locations', '{"settings":{"autovacuum_vacuum_threshold":50,"autovacuum_vacuum_scale_factor":0.2},"tables":[{"relname":"courier_locations","reltuples":120000,"n_live_tup":120000,"n_dead_tup":4800000,"options":{"autovacuum_vacuum_scale_factor":0.01,"autovacuum_vacuum_threshold":1000}},{"relname":"orders","reltuples":2000000,"n_live_tup":2000000,"n_dead_tup":100000,"options":{}}],"sessions":[{"pid":4242,"state":"idle in transaction","xmin_age":9000000},{"pid":5100,"state":"active","xmin_age":1200}],"slots":[{"slot_name":"replica_1","active":true,"xmin_age":900}],"max_xmin_age":1000000}', '{"tables":{"courier_locations":"blocked by pid 4242","orders":"ok"},"blocker":"pid 4242"}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 'courier_locations is due under its own storage parameters, not under the defaults', '{"settings":{"autovacuum_vacuum_threshold":50,"autovacuum_vacuum_scale_factor":0.2},"tables":[{"relname":"courier_locations","reltuples":120000,"n_live_tup":120000,"n_dead_tup":5000,"options":{"autovacuum_vacuum_scale_factor":0.01,"autovacuum_vacuum_threshold":1000}},{"relname":"orders","reltuples":2000000,"n_live_tup":2000000,"n_dead_tup":300000,"options":{}}],"sessions":[{"pid":5100,"state":"active","xmin_age":1200}],"slots":[{"slot_name":"replica_1","active":true,"xmin_age":900}],"max_xmin_age":1000000}', '{"tables":{"courier_locations":"vacuum lagging","orders":"ok"},"blocker":null}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 'An inactive replication slot holds the horizon', '{"settings":{"autovacuum_vacuum_threshold":50,"autovacuum_vacuum_scale_factor":0.2},"tables":[{"relname":"courier_locations","reltuples":120000,"n_live_tup":120000,"n_dead_tup":3000000,"options":{"autovacuum_vacuum_scale_factor":0.01,"autovacuum_vacuum_threshold":1000}},{"relname":"orders","reltuples":2000000,"n_live_tup":2000000,"n_dead_tup":50000,"options":{}}],"sessions":[{"pid":5100,"state":"active","xmin_age":1200}],"slots":[{"slot_name":"old_replica","active":false,"xmin_age":50000000},{"slot_name":"replica_1","active":true,"xmin_age":900}],"max_xmin_age":1000000}', '{"tables":{"courier_locations":"blocked by slot old_replica","orders":"ok"},"blocker":"slot old_replica"}', 5, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 'orders with 500,000 dead rows is past the trigger of 400,050', '{"settings":{"autovacuum_vacuum_threshold":50,"autovacuum_vacuum_scale_factor":0.2},"tables":[{"relname":"courier_locations","reltuples":120000,"n_live_tup":120000,"n_dead_tup":1000,"options":{"autovacuum_vacuum_scale_factor":0.01,"autovacuum_vacuum_threshold":1000}},{"relname":"orders","reltuples":2000000,"n_live_tup":2000000,"n_dead_tup":500000,"options":{}}],"sessions":[{"pid":5100,"state":"active","xmin_age":1200}],"slots":[],"max_xmin_age":1000000}', '{"tables":{"courier_locations":"ok","orders":"vacuum lagging"},"blocker":null}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 'A session and a slot both hold the horizon: the oldest one is reported', '{"settings":{"autovacuum_vacuum_threshold":50,"autovacuum_vacuum_scale_factor":0.2},"tables":[{"relname":"courier_locations","reltuples":120000,"n_live_tup":120000,"n_dead_tup":3000000,"options":{"autovacuum_vacuum_scale_factor":0.01,"autovacuum_vacuum_threshold":1000}},{"relname":"orders","reltuples":2000000,"n_live_tup":2000000,"n_dead_tup":450000,"options":{}}],"sessions":[{"pid":4242,"state":"idle in transaction","xmin_age":9000000},{"pid":5100,"state":"active","xmin_age":1200}],"slots":[{"slot_name":"old_replica","active":false,"xmin_age":50000000}],"max_xmin_age":1000000}', '{"tables":{"courier_locations":"blocked by slot old_replica","orders":"blocked by slot old_replica"},"blocker":"slot old_replica"}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pgp_182'), 'A young transaction is not a blocker: 10,000 dead rows is plain lag', '{"settings":{"autovacuum_vacuum_threshold":50,"autovacuum_vacuum_scale_factor":0.2},"tables":[{"relname":"courier_locations","reltuples":120000,"n_live_tup":120000,"n_dead_tup":10000,"options":{"autovacuum_vacuum_scale_factor":0.01,"autovacuum_vacuum_threshold":1000}},{"relname":"orders","reltuples":2000000,"n_live_tup":2000000,"n_dead_tup":200000,"options":{}}],"sessions":[{"pid":4242,"state":"idle in transaction","xmin_age":800000}],"slots":[{"slot_name":"replica_1","active":true,"xmin_age":900}],"max_xmin_age":1000000}', '{"tables":{"courier_locations":"vacuum lagging","orders":"ok"},"blocker":null}', 5, false, true, 6);
